actions.script:
const term = String(ec.web.parameters.term || '').trim().toLowerCase()
const selected = String(ec.web.parameters.value || '').trim()
const services = String(ec.web.parameters.kind || '') === 'service'
let names = []
if (term.length >= 2) {
    const all = services ? ec.service.getKnownServiceNames() : ec.entity.getAllEntityNames()
    // 0 the own name is the term, 1 it (or a service's noun) begins with it, 2 it holds it, 3 the package does
    const rank = name => {
        const lower = name.toLowerCase()
        const own = lower.slice(lower.lastIndexOf('.') + 1)
        return own === term ? 0 : own.startsWith(term) || own.slice(own.indexOf('#') + 1).startsWith(term) ? 1 : own.includes(term) ? 2 : 3
    }
    names = Array.from(all || []).map(String).filter(name => name.toLowerCase().includes(term))
        .map(name => [rank(name), name]).sort((first, second) => first[0] - second[0] || first[1].localeCompare(second[1]))
        .slice(0, 50).map(ranked => ranked[1])
} else if (selected) {
    names = [selected]
}
ec.web.sendJsonResponse(names.map(name => ({value: name, label: name})))

const L = text => ec.l10n.localize(text)
const number = (value, pattern) => ec.l10n.format(Number(value), pattern || '#,##0')
const DASH = '—'
const bytes = value => {
    const units = ['B', 'KiB', 'MiB', 'GiB', 'TiB']
    let amount = Number(value), unit = 0
    while (amount >= 1024 && unit < units.length - 1) { amount /= 1024; unit++ }
    return number(amount, amount >= 100 || unit === 0 ? '#,##0' : '#,##0.#') + ' ' + units[unit]
}
// each read on its own: a failure is logged and the rest of the page still shows
const read = (name, body, fallback) => {
    try { return body() } catch (error) { ec.logger.error('Tools home: ' + name + ' failed: ' + String(error)); return fallback }
    finally { ec.message.clearErrors() }
}
// a service's answer, empty when it refused
const call = (name, parameters) => read(name, () => {
    const out = ec.service.sync().name('org.moqui.dev.' + name).parameters(parameters || {}).call() || {}
    return ec.message.hasError() ? {} : out
}, {})

// ---- instance: the purpose, the database, and what the user may do here ----
const report = read('runtime report', () => ec.factory.getStartupReport(), null) || {}
isProduction = report.purpose === 'production'
// the database: db, else the last choice, else the default group's (template/DatabaseParts.xml)
databaseList = Array.from(call('DatabaseServices.get#DatabaseList', {includeExternal: false}).databases || [])
    .map(database => Object.assign({}, database, {groupNames: database.groupNames || [],
        label: database.external ? (database.description || database.db) + ' (external)'
            : (database.groupNames || []).join(', ') + ' (' + database.databaseConf + ')'}))
db = [db, ec.user.getPreference('database.selected')].find(name => databaseList.some(database => database.db == name)) ||
    (databaseList[0] || {}).db || null
selectedDatabase = databaseList.find(database => database.db == db) || null
// what the database says of itself, kept five minutes by the service
const facts = db ? call('DatabaseServices.get#Capabilities', {db}) : {}
const BACKENDS = {'embedded-postgres': L('embedded PostgreSQL'), postgres: 'PostgreSQL', mysql: 'MySQL', mariadb: 'MariaDB'}
const version = /[0-9]+(\.[0-9]+)*/.exec(String(facts.version || ''))
instanceText = [report.purpose, [BACKENDS[facts.backend] || facts.backend || (selectedDatabase || {}).databaseConf, version ? version[0] : '']
    .filter(part => part).join(' '), selectedDatabase ? L('database') + ': ' + selectedDatabase.label : ''].filter(part => part).join(' · ')
abilityRows = [['SQL_RUNNER_WEB', L('SQL')], ['DATABASE_ADMIN', L('Database admin')], ['DATABASE_EXTERNAL', L('External databases')],
    ['LOAD_RUNNER', L('Load testing')]].map(([permission, text]) => {
        const held = ec.user.hasPermission(permission)
        return {text, held, tooltip: (held ? L('You hold the permission') : L('Needs the permission')) + ' ' + permission}
    })
canSql = abilityRows[0].held
canLoadRunner = abilityRows[3].held

// ---- counters: the model as Artifact summary counts it, and the selected database's size ----
let entities = 0, viewEntities = 0
read('entity counts', () => {
    for (const info of Array.from(ec.entity.getAllEntityInfo(1, false) || [])) { entities += Number(info.entities || 0); viewEntities += Number(info.viewEntities || 0) }
})
entityCountText = number(entities)
viewEntityCountText = number(viewEntities)
serviceCountText = number(read('service count', () => Array.from(ec.service.getKnownServiceNames()).length, 0))
ecaCountText = number(read('ECA rule count', () => Number(ec.entity.getEecaRuleCount()) + Number(ec.service.getSecaRuleCount()), 0))
// the screens are counted by a walk of every screen, two seconds the first time in a process: the service
// answers the count it kept and has it counted on a worker when it has none or the one it has is old
const screens = read('screen count', () => ec.service.sync().name('moqui.tools.ToolsHomeServices.get#ScreenCount').call() || {}, {})
// the last Check Tables run of this process (Schema › Entities keeps it): the differences it found and changed
const tableCheck = read('table check', () => JSON.parse(ec.cache.getCache('tools.home.counts').get('checkTables') || 'null'), null)
tableCheckShown = !!tableCheck
tableCheckText = tableCheck ? number(tableCheck.statements) : ''
tableCheckTitle = tableCheck ? L('Schema differences') + ' · ' + L('checked') + ' ' + ec.l10n.format(new Date(Number(tableCheck.time)), 'HH:mm') +
    (tableCheck.failed ? ' · ' + number(tableCheck.failed) + ' ' + L('failed') : '') : ''
tableCheckStyle = tableCheck && tableCheck.failed ? 'text-warning' : ''
screenCountText = screens.screenCount != null ? number(screens.screenCount) : '…'
screenCountTitle = screens.screenCount != null ? L('Screens') : L('Screens') + ' · ' + L('being counted')
databaseSizeText = facts.databaseSize != null ? bytes(facts.databaseSize) : DASH
databaseSizeTitle = facts.databaseSize != null ? L('Database size') : L('Database size') + ' · ' + L('not reported')

// ---- pick up where you left off: recent entities, saved grid views, saved queries, SQL history ----
const oneLine = text => { const line = String(text || '').replace(/\s+/g, ' ').trim(); return line.length > 80 ? line.slice(0, 79) + '…' : line }
const leftOff = [
    read('recent entities', () => ec.resource.script('component://tools/template/ToolsRecent.js').read()
        .filter(name => ec.entity.isEntityDefined(name)), [])
        .map(name => ({text: name, kindText: L('entity'), rowLink: '../Data/Grid', rowParameters: {entityName: name}})),
    Array.from(call('DatabaseServices.find#GridViews').gridViews || [])
        .map(view => ({text: String(view.description || view.viewId), kindText: L('grid view'), rowLink: '../Data/Grid',
            rowParameters: {viewId: view.viewId}})),
    canSql ? Array.from(call('DatabaseServices.find#SavedQueries').savedQueries || [])
        .map(query => ({text: String(query.description || query.queryId), kindText: L('saved query'), rowLink: '../Sql',
            rowParameters: {queryId: query.queryId, db: query.db || ''}})) : [],
    canSql ? Array.from(call('DatabaseServices.find#SqlHistory', {limit: 10}).history || [])
        .map(item => ({text: oneLine(item.statementText), kindText: L('SQL history'), rowLink: '../Sql',
            rowParameters: {auditId: item.auditId, db: item.db || ''}})) : []
]
// ten rows: four entities and two of each other kind, then more of each in that order while there is room
const LEFT_OFF = 10
const taken = leftOff.map((rows, index) => rows.slice(0, index === 0 ? 4 : 2))
let room = LEFT_OFF - taken.reduce((total, rows) => total + rows.length, 0)
for (let index = 0; room > 0 && index < leftOff.length; index++) {
    const more = leftOff[index].slice(taken[index].length, taken[index].length + room)
    taken[index] = taken[index].concat(more)
    room -= more.length
}
recentRows = [].concat(...taken)
hasRecent = recentRows.length > 0

// ---- running and recent: the latest five ETL runs, database jobs and load runs, newest first ----
const STATES = {pending: [L('Pending'), 'grey-7'], running: [L('Running'), 'primary'], done: [L('Completed'), 'positive'],
    failed: [L('Failed'), 'negative'], stopped: [L('Stopped'), 'warning'], cancelled: [L('Cancelled'), 'warning'], skipped: [L('Skipped'), 'warning']}
const ETL_STATES = {EtlrPending: 'pending', EtlrRunning: 'running', EtlrDone: 'done', EtlrFailed: 'failed'}
const JOB_STATES = {DbjsPending: 'pending', DbjsRunning: 'running', DbjsDone: 'done', DbjsFailed: 'failed', DbjsCancelled: 'cancelled', DbjsSkipped: 'skipped'}
const LOAD_STATES = {running: 'running', completed: 'done', stopped: 'stopped', failed: 'failed'}
// a time of a run: a timestamp, epoch milliseconds or an RFC 3339 text, as epoch milliseconds
const digits = /^[0-9]+$/, scriptDir = /^.*\//, loadJs = /\.load\.js$/
const millis = value => {
    if (value == null || value === '') return null
    const text = String(value)
    try { return Number(String(basicConvert(digits.test(text) ? Number(text) : text, 'Timestamp'))) } catch (error) { return null }
}
const today = ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')
const timeText = at => {
    if (at == null || !Number.isFinite(at)) return ''
    const stamp = basicConvert(at, 'Timestamp')
    return ec.l10n.format(stamp, ec.l10n.format(stamp, 'yyyy-MM-dd') === today ? 'HH:mm' : 'MMM d')
}
const running = (kindText, text, state, start, rowLink, rowParameters) => {
    const shown = STATES[state] || [DASH, 'grey-7']
    const at = millis(start)
    return {kindText, text: oneLine(text), stateText: shown[0], stateColor: shown[1], at, timeText: timeText(at), rowLink, rowParameters}
}
// a run is named by its mapping, read once for each mapping of the five runs
const mappingNames = {}
const mappingName = mappingId => {
    if (!mappingId) return ''
    if (!(mappingId in mappingNames)) mappingNames[mappingId] = read('ETL mapping ' + mappingId, () =>
        (ec.entity.find('moqui.etl.EtlMapping').condition('mappingId', mappingId).one() || {}).description, '') || String(mappingId)
    return mappingNames[mappingId]
}
runningRows = [].concat(
    Array.from(call('EtlServices.get#EtlRuns', {limit: 5}).runs || []).map(run => running(L('ETL'),
        mappingName(run.mappingId) || run.runId, ETL_STATES[run.statusId], run.startTime, '../Etl/Run', {runId: run.runId})),
    Array.from(call('DatabaseServices.get#DatabaseJobs', {limit: 5}).jobs || []).map(job => running(L('Job'),
        job.description || job.jobId, JOB_STATES[job.statusId], job.startTime || job.createdDate, '../Database/JobDetail', {jobId: job.jobId})),
    canLoadRunner ? Array.from(call('LoadServices.find#LoadRuns').runs || []).slice(0, 5).map(run => running(L('Load'),
        run.label || String(run.script || '').replace(scriptDir, '').replace(loadJs, '') || run.runId, LOAD_STATES[run.status], run.start,
        '../Load/Run', {runId: run.runId})) : []
).sort((first, second) => (second.at || 0) - (first.at || 0))
hasRunning = runningRows.length > 0

// ---- navigation: the catalog of template/HomeParts.xml (a component adds entries with an actions-extend) ----
const featured = (path, title, text, links) => ({path, title, text, links, featured: true})
const entry = (group, path, title, icon, parameters) => ({group, path, title, icon, parameters})
const data = L('Data'), schema = L('Schema and database'), services = L('Services and reference'), load = L('Load testing'),
    elsewhere = L('Elsewhere')
// Dev AIDE is linked when its app is mounted beside this one (a dev instance)
const devAide = ec.resource.script('component://tools/template/HomeCatalog.js').devMounted(sri, ec)
navOptions = {otherTitle: L('More')}
navCatalog = [
    featured('Data/Grid', L('Data grid'), L('Find and edit records of an entity, a view, a SQL result or a file'),
        [{path: 'Data/Grid', title: L('Open a file'), parameters: {open: 'file'}}, {path: 'Data/Grid', title: L('Saved views'), parameters: {open: 'views'}}]),
    // SQL only for a holder of SQL_RUNNER_WEB: without it the screen is named and not shown
    Object.assign(featured('Sql', L('SQL'), L('Run statements, read only or with changes confirmed'),
        [{path: 'Sql', title: L('History'), parameters: {open: 'history'}}, {path: 'Sql', title: L('Saved queries'), parameters: {open: 'saved'}}]),
        {hidden: !canSql}),
    featured('Schema/Entities', L('Entities'), L('Definitions, tables and their differences'),
        [{path: 'Schema/Entities', title: L('Check tables')}, {path: 'Schema/IndexesKeys', title: L('Indexes, keys')}]),
    featured('Service', L('Services'), L('Inputs, results and the rules of any service; run one'),
        [{path: 'Service/ServiceRun', title: L('Run a service')}]),
    featured('Database', L('Database'), L('Sessions, statements, tables, maintenance and jobs'),
        [{path: 'Database/Activity'}, {path: 'Database/Tables'}, {path: 'Database/Jobs'}]),
    featured('Etl', L('ETL'), L('Mappings that load a file or a query into entities'),
        [{path: 'Etl/Runs'}, {path: 'Etl/ValueMaps', title: L('Value maps')}]),

    entry(data, 'Data/Browse', L('Browse related'), 'sym_o_account_tree'), entry(data, 'Data/Views', '', 'sym_o_view_column'),
    entry(data, 'Data/Documents'), entry(data, 'Data/Load', '', 'sym_o_upload'), entry(data, 'Data/Export', '', 'sym_o_download'),
    entry(data, 'Data/Snapshots', '', 'sym_o_photo_camera'),

    entry(schema, 'Schema/IndexesKeys', '', 'sym_o_key'), entry(schema, 'Database/Queries', L('Statement statistics'), 'sym_o_query_stats'),
    entry(schema, 'Database/Settings', L('Database settings'), 'sym_o_tune'), entry(schema, 'Database/SpeedTest', L('Speed test'), 'sym_o_speed'),

    entry(services, 'StatusFlows', L('Status flows')), entry(services, 'ArtifactStats'), entry(services, 'RestApi'),
    entry(services, 'RestApi', L('Entity master API'), 'sym_o_data_object', {api: 'entity'}),
    {group: services, url: '//apps/system/Monitor/Artifacts', title: L('Artifact performance'), icon: 'sym_o_deployed_code',
        parameters: {'var-artifactType': 'AT_SERVICE'}},

    entry(load, 'Load/Scripts', '', 'sym_o_description'), entry(load, 'Load/Runs', '', 'sym_o_play_circle'),

    {group: elsewhere, url: '//apps/Terminal', title: L('Terminal UI'), icon: 'sym_o_terminal'},
    {group: elsewhere, url: '//apps/ScreenTree', title: L('Site map'), icon: 'sym_o_map'},
    devAide ? {group: elsewhere, url: '//apps/dev', title: L('Dev AIDE'), icon: 'sym_o_code_blocks'} : null,
    {group: elsewhere, url: '//apps/system/Monitor', title: L('System › Monitor'), icon: 'sym_o_monitoring'}
].filter(item => item)
